window.T17_DASHBOARD_UNITS = [{"unit":1,"theme":"additional – electricity","cards":[{"w":"additional","p":"adj.","d":"added, extra, or supplementary to what is already present or available","c":"額外的；附加的","s":"Ordering breakfast to your hotel room requires an additional charge of ten dollars.","t":"將早餐點送至飯店客房需要十美元的額外費用。"},{"w":"advantage","p":"n.","d":"a condition or circumstance that puts one in a favorable or superior position","c":"優勢；好處；利益（可數/不可數）","s":"She decided to take advantage of the sunny afternoon by having a relaxing walk in the park.","t":"她決定利用陽光明媚的午後在公園裡輕鬆散步。"},{"w":"banker","p":"n.","d":"an officer or owner of a bank, or a person who manages financial investments","c":"銀行家；銀行高級職員（可數）","s":"In spite of his remarkable financial success, the wealthy banker had yet to find true happiness in life.","t":"儘管取得了顯著的財務成就，那位富有的銀行家在生活中仍未找到真正的幸福。"},{"w":"carpet","p":"n./v.","d":"a thick floor covering made of woven fabric; to cover thickly as if with a carpet","c":"地毯（名詞）；覆蓋厚厚一層（動詞）","s":"The host hotel rolled out the red carpet to welcome the international diplomats.","t":"主辦飯店鋪上了紅地毯以隆重歡迎各國外交官。"},{"w":"compete","p":"v.","d":"to strive to gain or win something by defeating or establishing superiority over others","c":"競爭；比賽（動詞）","s":"Dozens of talented young athletes from across the country arrived to compete in the national championship.","t":"來自全國各地的數十名才華洋溢的年輕運動員抵達現場參加全國錦標賽的角逐／競爭。"},{"w":"decorate","p":"v.","d":"to make something look more attractive by adding ornament or color","c":"裝飾；裝潢；點綴（動詞）","s":"The cheerful children used colorful balloons and paper ribbons to decorate the classroom for Christmas.","t":"開朗的孩子們用彩色氣球和紙絲帶裝飾教室以迎接聖誕節。"},{"w":"dislike","p":"v./n.","d":"to feel distaste for or hostility toward; a feeling of distaste or hostility","c":"不喜歡；厭惡（動詞/名詞）","s":"What I dislike most about living in a bustling metropolitan city is the severe air pollution.","t":"住在繁忙大都市裡我最不喜歡的一點就是嚴重的空氣污染。"},{"w":"electricity","p":"n.","d":"a form of energy resulting from the existence of charged particles, used for power","c":"電；電力（不可數）","s":"In order to save electricity during the peak summer hours, citizens are advised to turn off unused air conditioners.","t":"為了在夏季尖峰時段節約電力，當局建議市民關閉未使用的冷氣機。"}]},{"unit":2,"theme":"flavor – jewel","cards":[{"w":"flavor","p":"n./v.","d":"the distinctive taste of a food or drink; to impart flavor to","c":"風味；口味（名詞）；給…調味（動詞）","s":"The experienced Italian chef likes to flavor his tomato pasta sauce with fresh basil and garlic.","t":"那位經驗豐富的義大利主廚喜歡用新鮮羅勒和大蒜為他的番茄義大利麵醬調味。"},{"w":"gap","p":"n.","d":"a break or hole in an object, or a wide difference in views or age","c":"缺口；間隔；分歧；差距（可數）","s":"There is a noticeable generation gap between elderly grandparents and tech-savvy teenagers.","t":"在年邁的祖父母與精通科技的青少年之間存在著明顯的代溝／差距。"},{"w":"handkerchief","p":"n.","d":"a small square piece of linen or silk carried in one's pocket for wiping the face","c":"手帕；手絹（可數）","s":"Marvin always carries a clean cotton handkerchief in his pocket to wipe his brow on humid days.","t":"馬文總是在口袋裡帶著一條乾淨的棉質手帕，以便在潮濕悶熱的天氣擦拭額頭。"},{"w":"handy","p":"adj.","d":"convenient to handle or use, or placed within easy reach","c":"便利的；手巧的；近便手邊的","s":"Carrying an umbrella in your backpack will definitely come in handy if sudden afternoon showers occur.","t":"如果午後突然下起陣雨，背包裡帶著一把雨傘肯定會派上用場。"},{"w":"hanger","p":"n.","d":"a curved piece of wood, plastic, or wire with a hook, used for hanging clothes","c":"衣架（可數）","s":"I ran completely out of plastic clothes hanger after doing three large loads of weekend laundry.","t":"洗完週末的三大籃衣服後，我的塑膠衣架完全用光了。"},{"w":"honesty","p":"n.","d":"the quality of being fair, truthful, and morally upright","c":"誠實；正直；率直（不可數）","s":"Darren confessed that he had broken the valuable vase, and the teacher truly appreciated his honesty.","t":"達倫坦白是他打破了那只昂貴的花瓶，老師由衷地欣賞他的誠實。"},{"w":"inferior","p":"adj./n.","d":"lower in rank, status, or quality; a person lower in rank or status","c":"較差的；次等的（形容詞）；下級／部屬（名詞）","s":"These imported counterfeit handbags are sold at low prices because they are made of inferior leather.","t":"這些進口仿冒手提包之所以廉價出售，是因為它們是用劣質／次等皮革製成的。"},{"w":"jewel","p":"n.","d":"a precious stone, typically a single crystal, or a highly valued thing","c":"寶石；珠寶；珍貴之物（可數）","s":"The royal exhibition displayed sparkling golden crowns set with dazzling rubies and precious jewels.","t":"皇家展覽展示了鑲嵌著耀眼紅寶石與珍貴寶石的閃爍金冠。"}]},{"unit":3,"theme":"knit – mist","cards":[{"w":"knit","p":"v./n.","d":"to make a garment by interlocking loops of wool with needles; a knitted fabric","c":"編織；針織（動詞）；針織品（名詞）","s":"Every winter, my caring grandmother sits quietly by the fireplace to knit warm wool socks for the family.","t":"每年冬天，慈祥的祖母總是靜靜坐在壁爐旁為全家編織溫暖的羊毛襪。"},{"w":"koala","p":"n.","d":"an Australian arboreal marsupial with thick gray fur and large ears","c":"無尾熊；考拉（可數）","s":"During our wonderful trip to Sydney, we visited a famous nature sanctuary to see a mother koala sleeping peacefully.","t":"在雪梨的美好旅行中，我們參觀了一處著名的自然保護區，看見一隻母無尾熊正平靜地熟睡著。"},{"w":"lace","p":"n./v.","d":"a fine delicate fabric made of yarn in an open webbed pattern; to fasten with laces","c":"蕾絲；鞋帶（名詞）；繫鞋帶（動詞）","s":"The graceful bride walked slowly down the aisle in an exquisite wedding gown decorated with vintage French lace.","t":"優雅的新娘身穿飾有復古法國蕾絲的精美婚紗緩步走過紅毯通道。"},{"w":"lately","p":"adv.","d":"not long ago; in recent times; recently","c":"近來；最近","s":"Dana looks quite exhausted because she has been working overtime at the advertising agency lately.","t":"黛娜看起來相當疲憊，因為她最近一直在廣告公司加班。"},{"w":"lawn","p":"n.","d":"an area of short, regularly mown grass in the yard of a house or in a park","c":"草坪；草地（可數）","s":"My father spends every sunny Saturday morning using an electric mower to cut the front lawn.","t":"我父親每逢陽光明媚的週六早晨都會使用電動除草機修剪前院草坪。"},{"w":"liberty","p":"n.","d":"the state of being free within society from oppressive restrictions","c":"自由；特權；自主權（不可數/可數）","s":"Millions of immigrants arriving in New York Harbor were inspired by the magnificent Statue of liberty.","t":"抵達紐約港的數百萬移民都受到了雄偉自由女神像的鼓舞。"},{"w":"lock","p":"n./v.","d":"a mechanism for keeping a door or lid fastened; to fasten or secure with a lock","c":"鎖（名詞）；鎖上；鎖好（動詞）","s":"Viola routinely forgets to lock the back door before leaving for her morning run in the park.","t":"薇奧拉在出門前往公園晨跑前，經常忘記把後門鎖上。"},{"w":"mist","p":"n./v.","d":"a cloud of tiny water droplets suspended in the atmosphere; to cover with mist","c":"薄霧；水汽（名詞）；蒙上薄霧（動詞）","s":"As dawn broke across the valley, the high mountain peaks were completely shrouded in thick morning mist.","t":"當破曉拂曉時分劃過山谷，高聳的山峰完全籠罩在濃濃的清晨薄霧中。"}]},{"unit":4,"theme":"plenty – stable","cards":[{"w":"plenty","p":"pron./n./adv.","d":"a large or sufficient amount or quantity; fully; quite","c":"大量；充足（代名詞/名詞）；十分；非常（副詞）","s":"Don't worry about dinner because we already have plenty of fresh vegetables and bread in the kitchen.","t":"別擔心晚餐，因為我們廚房裡已經有許多／大量的新鮮蔬菜和麵包。"},{"w":"pretend","p":"v.","d":"to behave so as to make it appear that something is the case when in fact it is not","c":"假裝；裝作；假扮（動詞）","s":"Young children love to pretend to be brave astronauts exploring unknown alien planets in outer space.","t":"小孩子們喜歡假扮／假裝成勇敢的太空人探索外太空未知的奇異星球。"},{"w":"pronounce","p":"v.","d":"to make the sound of a word or letter with your voice; to declare officially","c":"發音；宣判；正式宣佈（動詞）","s":"Because French vowels are difficult for foreign beginners, the teacher showed us how to pronounce them correctly.","t":"因為法語母音對外國初學者而言很難，老師向我們示範了如何正確發音。"},{"w":"protection","p":"n.","d":"the state of being kept safe from harm, damage, or loss","c":"保護；防護（不可數）","s":"All construction workers are legally required to wear sturdy hard hats for head protection on site.","t":"法律規定所有建築工人在工地上都必須戴上結實的安全帽以提供頭部保護。"},{"w":"reveal","p":"v.","d":"to make known to others previously secret or unknown information","c":"揭露；洩漏；透露（動詞）","s":"The investigative journalist promised not to reveal the identity of his confidential informant.","t":"那位調查記者承諾絕不透露／洩漏他機密線人的身分。"},{"w":"saving","p":"n.","d":"an economy of or reduction in money, time, or resources; money saved in a bank","c":"節約；節省（單數）；積蓄；存款（複數 savings）","s":"After forty years of hard manual labor, Mr. Turner invested his life savings into a small bookstore.","t":"辛勤從事體力勞動四十年後，特納先生將他一生的積蓄投資開了一家小書店。"},{"w":"spaghetti","p":"n.","d":"pasta made in long, slender, solid strings, typically served with sauce","c":"義大利麵（不可數）","s":"Whenever our Italian grandparents visit us, they cook a delicious meal of homemade spaghetti with meat sauce.","t":"每當我們義大利籍的祖父母來訪時，他們都會煮一頓美味的自製肉醬義大利麵。"},{"w":"stable","p":"adj./n.","d":"not likely to change, fail, or collapse; a building in which horses are kept","c":"穩定的；牢固的（形容詞）；馬廄（名詞）","s":"Following the delicate heart surgery, the hospital nurse announced that the patient was in stable condition.","t":"在精細的心臟手術之後，醫院護理師宣佈該病患目前情況穩定。"}]},{"unit":5,"theme":"strip – warn","cards":[{"w":"strip","p":"n./v.","d":"a long narrow piece of cloth, paper, or land; to remove clothing or covering","c":"長條；帶狀物（名詞）；脫掉衣服；剝奪（動詞）","s":"Every Sunday morning, my little brother laughs out loud while reading the funny comic strip in the newspaper.","t":"每逢週日早晨，我弟弟看報紙上的幽默連環漫畫時總是開懷大笑。"},{"w":"volume","p":"n.","d":"the amount of space occupied by a substance, the loudness of sound, or a single book","c":"音量；體積；容量；冊；卷（可數/不可數）","s":"Please turn down the television volume so that your grandfather can take a peaceful nap in the bedroom.","t":"請調小電視音量，好讓你的祖父能在臥室裡安靜小睡。"},{"w":"wander","p":"v./n.","d":"to walk or move in a leisurely, casual, or aimless way; an aimless stroll","c":"漫遊；閒逛；徘徊（動詞/名詞）","s":"While sitting through the long chemistry lecture, David's tired mind began to wander to his upcoming vacation.","t":"在冗長的化學講座中，大衛疲憊的思緒開始神遊／走神到即將到來的假期。"},{"w":"warn","p":"v.","d":"to inform someone in advance of an impending danger, problem, or other unpleasant situation","c":"警告；告誡；提醒（動詞）","s":"The experienced park ranger strictly warned all hikers about the dangerous wild bears living in the mountains.","t":"經驗豐富的公園巡邏員嚴格告誡所有健行者，山中有危險的野生熊出沒。"}]}];
